"use strict";(globalThis.webpackChunkmy_website||=[]).push([[86965],{32682(e){e.exports=JSON.parse('{"slug":"hard-fork-combinator","title":"Hard Fork Combinator","short":"Cardano\'s mechanism for stitching protocol era transitions onto a single live chain without splitting it.","category":"network","aliases":["HFC"],"mentalModel":null,"related":["hard-fork","byron","shelley","goguen","voltaire"],"sources":[],"link":null,"level":"intermediate","body":"A piece of Cardano\'s consensus design that lets the protocol\'s rule set switch, for example from the Byron rules to the Shelley rules, while the underlying chain keeps growing as one. Older blocks remain valid in the new era\'s view of the world, and the network does not need to be paused or split to enable the change.\\n\\nThe combinator is what makes hard forks on Cardano feel like seamless upgrades rather than coordinated chain-restart events."}')}}]);